function initScrollReveal(){const e=document.querySelectorAll('.article-card, .letter-card, .hub-card, .interview-card, .artwork-card, .book-card, .diwan-card, .about-wrapper, .privacy-panel, .contact-card, .poems-hub-wrapper');if(!e.length)return;const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.style.opacity='1',e.target.style.transform='translateY(0)',t.unobserve(e.target))})},{threshold:.08});e.forEach(e=>{e.style.opacity='0',e.style.transform='translateY(20px)',e.style.transition='opacity 0.45s ease, transform 0.45s ease',t.observe(e)})}function initNavbarAutoClose(){const e=document.querySelector('.navbar-collapse');if(!e)return;document.querySelectorAll('.navbar-nav .nav-link').forEach(t=>{t.addEventListener('click',o=>{t.classList.contains('dropdown-toggle')||(!e.classList.contains('show')||(o=bootstrap.Collapse.getInstance(e))&&o.hide())})});document.querySelectorAll('.dropdown-menu .dropdown-item').forEach(t=>{t.addEventListener('click',()=>{if(e.classList.contains('show')){const t=bootstrap.Collapse.getInstance(e);t&&t.hide()}})})}function highlightActiveDropdownItem(){const e=new URLSearchParams(window.location.search).get('slug');e&&document.querySelectorAll('.dropdown-item').forEach(t=>{t.href.includes(`slug=${e}`)&&t.classList.add('active','fw-bold')})}document.addEventListener('DOMContentLoaded',()=>{initScrollReveal();initNavbarAutoClose();highlightActiveDropdownItem()});